import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import mongoose from 'mongoose';
import 'dotenv/config';
import Scheme from '../models/Scheme.js';
import SchemeChunk from '../models/SchemeChunk.js';
import IngestionJob from '../models/IngestionJob.js';
import { chunkScheme } from './chunker.js';
import { getEmbedding } from '../utils/embeddings.js';

/**
 * Adapter for myscheme-scraper output.
 * Reads JSON output files generated by the Playwright scraper, computes
 * content hash, and performs incremental update of schemes & vector chunks.
 */
export async function ingestScraperOutput(scrapedDataOrFilePath) {
    let rawSchemes = [];

    if (typeof scrapedDataOrFilePath === "string") {
        if (!fs.existsSync(scrapedDataOrFilePath)) {
            throw new Error(`Scraper output file not found: ${scrapedDataOrFilePath}`);
        }
        const fileContent = fs.readFileSync(scrapedDataOrFilePath, "utf8");
        rawSchemes = JSON.parse(fileContent);
    } else if (Array.isArray(scrapedDataOrFilePath)) {
        rawSchemes = scrapedDataOrFilePath;
    } else {
        throw new Error("Invalid scraper input: must be file path or scheme array");
    }

    const jobId = `scrape_ingest_${Date.now()}`;
    const job = new IngestionJob({
        jobId,
        type: "incremental",
        status: "running",
        source: "myscheme-scraper"
    });
    await job.save();

    let newCount = 0;
    let updatedCount = 0;
    let unchangedCount = 0;
    let chunkCount = 0;

    try {
        for (const item of rawSchemes) {
            const title = item.name || item.title || item.schemeName || "Untitled Scheme";
            const slug = item.slug || item.id || title.toLowerCase().replace(/[^a-z0-9]+/g, "-");

            const description = item.description || item.briefDescription || "";
            const eligibility = item.eligibility || item.eligibilityCriteria || "";
            const benefits = item.benefits || item.financialAssistance || "";
            const applicationProcess = item.applicationProcess || item.howToApply || "";
            const documentsRequired = item.documentsRequired || item.documents || "";

            // Compute content hash to detect changes
            const contentHash = crypto.createHash("sha256")
                .update(`${title}|${description}|${eligibility}|${benefits}|${applicationProcess}`)
                .digest("hex");

            const existing = await Scheme.findOne({ schemeId: slug });

            if (existing && existing.contentHash === contentHash) {
                // Content unchanged: skip expensive re-chunking and re-embedding
                unchangedCount++;
                continue;
            }

            const schemeDoc = {
                schemeId: slug,
                title,
                level: (item.level || "").toLowerCase().includes("state") ? "State/UT" : "Central",
                stateOrMinistry: item.ministry || item.state || item.nodalMinistry || "Government of India",
                applicationMode: item.mode || "Online",
                tags: Array.isArray(item.tags) ? item.tags : (item.tags ? [item.tags] : []),
                description,
                eligibility,
                benefits,
                applicationProcess,
                documentsRequired,
                sourceUrl: item.url || `https://www.myscheme.gov.in/schemes/${slug}`,
                sourcePortal: "myscheme.gov.in",
                contentHash,
                version: existing ? existing.version + 1 : 1,
                lastScrapedAt: new Date(),
                updatedAt: new Date()
            };

            await Scheme.findOneAndUpdate({ schemeId: slug }, schemeDoc, { upsert: true, new: true });

            if (!existing) newCount++;
            else updatedCount++;

            // Re-index chunks
            const chunks = chunkScheme(schemeDoc);
            await SchemeChunk.deleteMany({ schemeId: slug });

            for (const chunk of chunks) {
                const vector = await getEmbedding(chunk.text, false);
                await SchemeChunk.create({
                    ...chunk,
                    embedding: vector
                });
                chunkCount++;
            }
        }

        job.status = "completed";
        job.stats = {
            totalSchemes: rawSchemes.length,
            newSchemes: newCount,
            updatedSchemes: updatedCount,
            unchangedSchemes: unchangedCount,
            chunksCreated: chunkCount,
            embeddingsGenerated: chunkCount,
            errors: 0
        };
        job.completedAt = new Date();
        await job.save();

        return job.stats;

    } catch (err) {
        job.status = "failed";
        job.errorLog.push({ schemeId: "adapter", error: err.message, timestamp: new Date() });
        job.completedAt = new Date();
        await job.save();
        throw err;
    }
}
